import React, { useEffect, useState, useRef } from "react";
import axios from "axios";
import { Line } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement
} from "chart.js";

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement);

function App() {
  const [data, setData] = useState([]);
  const [page, setPage] = useState("dashboard");
  const [loading, setLoading] = useState(true);
  const [boxes, setBoxes] = useState([]);

  const videoRef = useRef(null);
  const canvasRef = useRef(null);

  // ================= LOAD DATA =================
  useEffect(() => {
    loadData();
    const interval = setInterval(loadData, 3000);
    return () => clearInterval(interval);
  }, []);

  const loadData = async () => {
    try {
      const res = await axios.get("http://127.0.0.1:8000/data");
      const cleanData = res.data.filter(d => d.waktu !== "None");
      setData(cleanData);
      setLoading(false);
    } catch (err) {
      console.log(err);
    }
  };

  const latest = data.length > 0 ? data[0] : null;

  // ================= CAMERA =================
  useEffect(() => {
    startCamera();
  }, []);

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      videoRef.current.srcObject = stream;
    } catch (err) {
      console.log("Camera error:", err);
    }
  };

  // ================= SEND FRAME =================
  const sendFrame = async () => {
    if (!videoRef.current || !canvasRef.current) return;

    const canvas = canvasRef.current;
    const video = videoRef.current;

    if (video.videoWidth === 0) return;

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;

    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    ctx.drawImage(video, 0, 0);

    canvas.toBlob(async (blob) => {
      const formData = new FormData();
      formData.append("file", blob, "frame.jpg");

      try {
        const res = await axios.post("http://127.0.0.1:8000/detect", formData);
        setBoxes(res.data.boxes || []);
      } catch (err) {
        console.log(err);
      }
    }, "image/jpeg");
  };

  // ================= LOOP DETECT =================
  useEffect(() => {
    const interval = setInterval(() => {
      sendFrame();
    }, 1500);

    return () => clearInterval(interval);
  }, []);

  // ================= DRAW BOX =================
  useEffect(() => {
    if (!canvasRef.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.strokeStyle = "lime";
    ctx.lineWidth = 3;

    boxes.forEach(box => {
      ctx.strokeRect(
        box.x1,
        box.y1,
        box.x2 - box.x1,
        box.y2 - box.y1
      );
    });

  }, [boxes]);

  // ================= CHART =================
  const chartData = {
    labels: data.map(d => d.waktu).reverse(),
    datasets: [
      {
        label: "Jumlah Orang",
        data: data.map(d => d.jumlah_orang).reverse(),
        borderColor: "#22c55e",
        tension: 0.4
      }
    ]
  };

  const getStatusColor = (kondisi) => {
    if (kondisi === "PEMBOROSAN") return "#ef4444";
    if (kondisi === "PERINGATAN") return "#f97316";
    return "#22c55e";
  };

  return (
    <div style={{ display: "flex", minHeight: "100vh", background: "#0f172a", color: "white" }}>

      {/* SIDEBAR */}
      <div style={{ width: 230, background: "#1e293b", padding: 20 }}>
        <h2>⚡ Hematrik</h2>
        <p onClick={() => setPage("dashboard")}>Dashboard</p>
        <p onClick={() => setPage("monitoring")}>Monitoring</p>
        <p onClick={() => setPage("history")}>History</p>
      </div>

      {/* CONTENT */}
      <div style={{ flex: 1, padding: 30 }}>

        {loading && <h2>Loading...</h2>}

        {/* DASHBOARD */}
        {!loading && page === "dashboard" && latest && (
          <>
            <h1>📊 Dashboard</h1>

            <div style={{
              padding: 15,
              background: getStatusColor(latest.kondisi),
              borderRadius: 10
            }}>
              {latest.notifikasi}
            </div>

            <div style={{ display: "flex", gap: 20, marginTop: 20 }}>
              <div style={card}><h3>People</h3><h1>{latest.jumlah_orang}</h1></div>
              <div style={card}><h3>Listrik</h3><h1>{latest.status_listrik}</h1></div>
              <div style={card}>
                <h3>Kondisi</h3>
                <h1 style={{ color: getStatusColor(latest.kondisi) }}>
                  {latest.kondisi}
                </h1>
              </div>
            </div>

            <div style={{ marginTop: 30 }}>
              <Line data={chartData} />
            </div>
          </>
        )}

        {/* MONITORING CCTV */}
        {page === "monitoring" && (
          <>
            <h1>📷 Live CCTV AI</h1>

            <div style={{ position: "relative", width: 500 }}>
              <video ref={videoRef} autoPlay style={{ width: "100%" }} />

              <canvas
                ref={canvasRef}
                style={{
                  position: "absolute",
                  top: 0,
                  left: 0,
                  width: "100%",
                  height: "100%"
                }}
              />
            </div>
          </>
        )}

        {/* HISTORY */}
        {page === "history" && (
          <>
            <h1>📜 History</h1>
            <table style={{ width: "100%" }}>
              <thead>
                <tr>
                  <th>Waktu</th>
                  <th>Orang</th>
                  <th>Listrik</th>
                  <th>Kondisi</th>
                </tr>
              </thead>
              <tbody>
                {data.map(d => (
                  <tr key={d.id}>
                    <td>{d.waktu}</td>
                    <td>{d.jumlah_orang}</td>
                    <td>{d.status_listrik}</td>
                    <td style={{ color: getStatusColor(d.kondisi) }}>
                      {d.kondisi}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </>
        )}

      </div>
    </div>
  );
}

const card = {
  background: "#1e293b",
  padding: 20,
  borderRadius: 10
};

export default App;
